#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Contract: deep water (seas and rivers) and abandoned shores.
 *
 * Rules: Knowledge Base articles 24 and 198 (shore = village directly beside a
 * deep-water tile; small ponds are not deep water). The generator only converts
 * tiles the caller releases, keeps clear of the start area and the Wonder of the
 * World sites, and the installed local world was regenerated by
 * tools/regenerate-waters.php without touching a claimed village.
 */

use Core\Database\DB;
use Game\Formulas;
use Game\Map\WaterGenerator;

function assertWater(bool $condition, string $message): void
{
    if (!$condition) {
        fwrite(STDERR, $message . PHP_EOL);
        exit(1);
    }
}

$root = dirname(__DIR__, 2);
require_once $root . '/game/deployment/include/env.php';
require_once $root . '/game/include/bootstrap.php';

$db = DB::getInstance();

// ---- generator ------------------------------------------------------------------
$size = 60;
$released = static fn (int $x, int $y): bool => ($x + $y) % 7 !== 0;
$generator = new WaterGenerator($size, $released);
$water = $generator->generate(42);
assertWater($water === (new WaterGenerator($size, $released))->generate(42), 'The same seed produces the same water.');
assertWater(count($water) > 0, 'A 121x121 map gets water.');
foreach ($water as [$x, $y]) {
    assertWater($released($x, $y), "Water at $x|$y was not released by the caller.");
    assertWater(hypot($x, $y) > WaterGenerator::PROTECTED_RADIUS, "Water at $x|$y is inside the protected start area.");
}
$none = (new WaterGenerator($size, static fn (): bool => false))->generate(7);
assertWater($none === [], 'Nothing is converted when no tile is released.');

// every body has at least MIN_BODY tiles (orthogonal connectivity)
$seen = [];
foreach ($water as $key => $start) {
    if (isset($seen[$key])) {
        continue;
    }
    $queue = [$start];
    $seen[$key] = true;
    $count = 0;
    while ($queue) {
        [$x, $y] = array_pop($queue);
        ++$count;
        foreach ([[1, 0], [-1, 0], [0, 1], [0, -1]] as [$dx, $dy]) {
            $nx = $generator->wrap($x + $dx);
            $ny = $generator->wrap($y + $dy);
            if (isset($water[$nx . '|' . $ny]) && !isset($seen[$nx . '|' . $ny])) {
                $seen[$nx . '|' . $ny] = true;
                $queue[] = [$nx, $ny];
            }
        }
    }
    assertWater($count >= $generator->minBody(), 'Water bodies smaller than minBody() tiles are dropped.');
}

// ---- size and shape on the reference map (MAP_SIZE 100) -------------------------------
// Where nothing blocks it the water covers 6 to 8 percent in a few solid seas plus rivers and large lakes.
$big = 100;
$cells = (2 * $big + 1) ** 2;
$open = new WaterGenerator($big, static fn (): bool => true);
foreach (range(1, 12) as $seed) {
    $sea = $open->generate($seed);
    $share = count($sea) / $cells;
    assertWater($share >= WaterGenerator::COVERAGE_MIN && $share <= WaterGenerator::COVERAGE_MAX, sprintf('Seed %d: water covers %.1f%% instead of 6 to 8%%.', $seed, $share * 100));
    $sizes = $open->bodySizes($sea);
    assertWater(count(array_filter($sizes, static fn (int $size): bool => $size >= WaterGenerator::SEA_MIN * 0.85)) >= 3, "Seed $seed: fewer than three seas of about 300 tiles or more.");
    assertWater(min($sizes) >= $open->minBody(), "Seed $seed: a body is smaller than minBody().");
    assertWater($sea === (new WaterGenerator($big, static fn (): bool => true))->generate($seed), "Seed $seed: not reproducible.");
    // Solid: land enclosed by a body that does not cross the world edge stays below 2 percent of the body.
    $seen = [];
    foreach ($sea as $key => $start) {
        if (isset($seen[$key])) {
            continue;
        }
        $body = [];
        $queue = [$start];
        $seen[$key] = true;
        while ($queue) {
            [$x, $y] = array_pop($queue);
            $body[$x . '|' . $y] = [$x, $y];
            foreach ([[1, 0], [-1, 0], [0, 1], [0, -1]] as [$dx, $dy]) {
                $nx = $open->wrap($x + $dx);
                $ny = $open->wrap($y + $dy);
                if (isset($sea[$nx . '|' . $ny]) && !isset($seen[$nx . '|' . $ny])) {
                    $seen[$nx . '|' . $ny] = true;
                    $queue[] = [$nx, $ny];
                }
            }
        }
        $xs = array_column($body, 0);
        $ys = array_column($body, 1);
        if (count($body) < 250 || min($xs) <= -$big || max($xs) >= $big || min($ys) <= -$big || max($ys) >= $big) {
            continue;
        }
        [$x0, $x1, $y0, $y1] = [min($xs) - 1, max($xs) + 1, min($ys) - 1, max($ys) + 1];
        $outside = [];
        $queue = [[$x0, $y0]];
        $outside[$x0 . '|' . $y0] = true;
        while ($queue) {
            [$x, $y] = array_pop($queue);
            foreach ([[1, 0], [-1, 0], [0, 1], [0, -1]] as [$dx, $dy]) {
                $nx = $x + $dx;
                $ny = $y + $dy;
                if ($nx < $x0 || $nx > $x1 || $ny < $y0 || $ny > $y1 || isset($body[$nx . '|' . $ny]) || isset($outside[$nx . '|' . $ny])) {
                    continue;
                }
                $outside[$nx . '|' . $ny] = true;
                $queue[] = [$nx, $ny];
            }
        }
        $enclosed = ($x1 - $x0 + 1) * ($y1 - $y0 + 1) - count($body) - count($outside);
        assertWater($enclosed <= 0.02 * count($body), sprintf('Seed %d: a body of %d tiles encloses %d land tiles.', $seed, count($body), $enclosed));
    }
}

// The installer places the water before anything else claims tiles and keeps decorations off it.
$installer = (string)file_get_contents($root . '/game/include/Model/InstallerModel.php');
assertWater(
    strpos($installer, '$this->createWaters();') < strpos($installer, '$rand = mt_rand(1, 8);')
        && str_contains($installer, "|| \$this->map[\$kid]['deepwater']"),
    'InstallerModel must create the waters before the landscape and keep landscape off water tiles.'
);

$shore = $generator->shoreOf($water);
assertWater(count($shore) > 0, 'Water has a shore.');
foreach ($shore as $key => [$x, $y]) {
    assertWater(!isset($water[$key]), 'A shore tile is never water.');
    $touches = false;
    foreach ($generator->neighbours($x, $y) as [$nx, $ny]) {
        $touches = $touches || isset($water[$nx . '|' . $ny]);
    }
    assertWater($touches, "Shore $key does not touch water.");
}
assertWater($generator->wrap($size + 1) === -$size && $generator->wrap(-$size - 1) === $size, 'Coordinates wrap at the map edge.');
$corner = [$size, $size];
assertWater(in_array([-$size, -$size], $generator->neighbours(...$corner), true), 'Shore neighbours wrap across the world edge.');

// ---- map art ----------------------------------------------------------------------
foreach (['60x60', '30x30', '6x6'] as $tile) {
    foreach (['', 'n', 'w', 's', 'e', 'nw', 'ne', 'ns', 'we', 'ws', 'se', 'nws', 'nwe', 'nse', 'wse', 'nwse'] as $mask) {
        $file = $mask === '' ? 'sea' : "sea-$mask";
        assertWater(is_file($root . "/game/deployment/public/img/map/sea/$tile/$file.png"), "Missing sea tile $tile/$file.png.");
    }
}
foreach ([
    'game/include/Controller/MapBlockCtrl.php' => ['setSea', 'img/map/sea/'],
    'game/include/Controller/Ajax/map/tileDetails.php' => ["\$tile['deepwater']", "'sea'", "(int)\$tile['shore']", '"Abandoned shore"'],
    'game/include/resources/Templates/map/viewTileDetails_fieldFree.php' => [" ' shore' "],
    'game/include/resources/Templates/map/viewTileDetails_fieldOccupied.php' => [" ' shore' "],
    'game/include/Model/InstallerModel.php' => ['createWaters', 'new WaterGenerator', 'deepwater, shore'],
    'tools/regenerate-waters.php' => ['occupied', 'oasistype', 'landscape', 'FROM vdata', '--replace', '--revert=', '$anchors', 'flushMapCaches', 'owner>0 OR did>0'],
] as $file => $needles) {
    $source = (string)file_get_contents($root . '/' . $file);
    foreach ($needles as $needle) {
        assertWater(str_contains($source, $needle), "$file must contain $needle.");
    }
}
$css = (string)file_get_contents($root . '/assets/gpack/travian/mainPage/css_ltr/imports.css');
assertWater(str_contains($css, '#tileDetails.landscape-sea .detailImage') && is_file($root . '/assets/gpack/travian/mainPage/img_ltr/legacy/views/map/detail-view/landscape/sea.jpg'), 'The Gpack carries the deep-water tile detail art.');

// ---- the installed world -------------------------------------------------------------
$hasColumns = (int)$db->fetchScalar("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='wdata' AND COLUMN_NAME IN ('deepwater','shore')") === 2;
assertWater($hasColumns, 'wdata must have deepwater and shore columns (database/world.sql).');
$installed = (int)$db->fetchScalar('SELECT COUNT(*) FROM wdata WHERE deepwater=1');
if ($installed > 0) {
    assertWater((int)$db->fetchScalar('SELECT COUNT(*) FROM wdata WHERE deepwater=1 AND (occupied=1 OR oasistype>0 OR landscape>0 OR fieldtype>0)') === 0, 'Water tiles are bare: no village site, oasis, landscape or occupant.');
    // A shore remains a shore after a player settles it; it is how Harbor villages are represented.
    assertWater((int)$db->fetchScalar('SELECT COUNT(*) FROM vdata v JOIN wdata w ON w.id=v.kid WHERE w.deepwater=1') === 0, 'No existing village sits on water.');
    assertWater((int)$db->fetchScalar('SELECT COUNT(*) FROM available_villages a JOIN wdata w ON w.id=a.kid WHERE w.deepwater=1') === 0, 'Water is never an available village site.');
    assertWater((int)$db->fetchScalar('SELECT COUNT(*) FROM wdata WHERE shore=1 AND (fieldtype=0 OR oasistype>0 OR landscape>0 OR deepwater=1)') === 0, 'Shore tiles are village sites.');
    assertWater((int)$db->fetchScalar('SELECT COUNT(*) FROM wdata WHERE shore=1') > 0, 'The world has shore village sites.');
}

echo "Water generator contract passed.\n";
